const CoursesComponent = ({isContactOpen,setIsContactOpen}) => {
  const openContact = () => {
    setIsContactOpen(true);
    document.body.style.overflow = 'hidden';
  };
  const closeContact = () => {
    setIsContactOpen(false);
    document.body.style.overflow = 'auto';
  };
  return (
    <section className="courses-section">
      <div className="container">
        <div className="section-header">
          <h2>Our Internship Courses</h2>
          <p className="subtitle">
            Choose your specialization and kickstart your career in tech
          </p>
          <div className="banner">
            <svg viewBox="0 0 1200 200" className="tech-banner">
              <path fill="#f5f5f5" d="M0,100 C150,200 450,0 600,100 S1050,200 1200,100 L1200,0 L0,0 Z"></path>
              <text x="50%" y="60%" textAnchor="middle" className="banner-text">Tech Internships</text>
              <text x="50%" y="80%" textAnchor="middle" className="banner-subtext">Hands-on experience with industry experts</text>
            </svg>
          </div>
        </div>

        <div className="courses-grid">
          {courses.map((course, index) => (
            <div key={index} className="course-card-container">
              <Link
                to={`/${course.url}`}
                className="course-card"
              >
                <div className="course-icon-container">
                  {course.icon}
                </div>
                <h3>{course.courseName}</h3>
                <div className="course-meta">
                  <span className="duration">{course.duration}</span>
                  <span className="level">{course.level}</span>
                </div>
                <p className="course-description">{course.description}</p>
                <div className="course-cta">
                  <span>View Details</span>
                  <span className="arrow"><BsArrowRight /></span>
                </div>
              </Link>
            </div>
          ))}
        </div>

        <div className="cta-section">
          <p>Not sure which course is right for you?</p>
          <button onClick={openContact} className="cta-button">
            Talk to an Advisor
          </button>
        </div>
      </div>
      {isContactOpen && (
        <div className="contact-modal-overlay">
          <ContactForm isPopup={true} onClose={closeContact} />
        </div>
      )}
    </section>
  );
};

export default CoursesComponent;